/** Assets whose source PNG has not been generated yet (full pack set
 *  minus what is currently built) — the contact sheet lists these as
 *  pending.
 */
export const PENDING_ASSETS: string[] = [];

const KNOWN = new Set(ASSETS.map((a) => a.name));

/** True when the named asset exists in the built pack (lets components
 *  skip optional art whose source image has not been generated yet).
 */
export function hasAsset(name: string): boolean {
  return KNOWN.has(name);
}
